style.css:
/* Hark — Quiet Intelligence | hark.com */

:root {
  /* swap these colors to change the whole mood */
  --my-bg: #f5f3ee;
  --my-surface: #fffefa;
  --my-text: #242b32;
  --my-muted: #858b91;
  --my-accent: #a6b9c0;
  --my-radius: 20px;
}

/* soft, atmospheric background */
body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
  font-family: Inter, -apple-system, BlinkMacSystemFont, sans-serif !important;
}

/* elegant headings */
h1, h2, h3 {
  color: var(--my-text) !important;
  letter-spacing: -0.045em !important;
  font-weight: 550 !important;
}

/* refined links */
a {
  color: #718d99 !important;
  text-decoration-thickness: 1px !important;
  text-underline-offset: 4px !important;
  transition: color 180ms ease !important;
}

/* smooth imagery */
img, video {
  border-radius: var(--my-radius) !important;
}

/* polished form controls */
input, textarea, select, button {
  border-radius: 12px !important;
  font-family: inherit !important;
}

/* gentle selection color */
::selection {
  background: #c8d9dc !important;
  color: #26363b !important;
}

/* subtle scrollbar */
* {
  scrollbar-color: #c3ccca transparent !important;
}
